import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import ApplicationWarningResolver from '../shared/ApplicationWarningResolver';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
import ApiService from '../../services/api';
import Scope3Cat5WastePanel from '../operations/Scope3Cat5WastePanel';

export type Scope3QualitySnapshot = {
  warnings?: string[];
  assuranceGradeReady?: boolean;
  scope3ExplicitlyMeasured?: boolean;
  residualScope3Used?: boolean;
  categoryCoverageCount?: number;
  categoriesWithActivityData?: string[];
};

export type Scope3RemediationAction = {
  category?: string;
  action?: string;
  path?: string;
  priority?: string;
  status?: string;
};

type Scope3Proposal = {
  transactionId: string;
  field: string;
  from?: string | null;
  to: string;
  confidence?: number;
  reason?: string;
};

type Scope3RemediationPanelProps = {
  scope3Quality?: Scope3QualitySnapshot | null;
  remediationActions?: Scope3RemediationAction[];
  period?: string;
  onResolved?: () => void;
};

const categoryHubLink = (category?: string): string => {
  const key = String(category || '').toLowerCase();
  if (
    key === 'transportation'
    || key === 'cat4_upstream_transport'
    || key === 'cat9_downstream_transport'
    || key === 'scope3_residual'
    || key === 'scope3_measurement'
  ) {
    return '/compliance/india?section=data-sync';
  }
  if (key === 'manufacturing' || key === 'cat3_fuel_energy_related') {
    return '/operations';
  }
  if (key.startsWith('cat6_') || key.startsWith('cat7_')) {
    return '/documents';
  }
  return DOCUMENT_UPLOAD_PATH;
};

const Scope3RemediationPanel: React.FC<Scope3RemediationPanelProps> = ({
  scope3Quality,
  remediationActions = [],
  period = 'annual',
  onResolved,
}) => {
  const warnings = scope3Quality?.warnings || [];
  const actions: Scope3RemediationAction[] = remediationActions.length > 0
    ? remediationActions
    : warnings.map((warning) => ({ action: warning, priority: 'high' }));

  const [proposals, setProposals] = useState<Scope3Proposal[]>([]);
  const [loadingProposals, setLoadingProposals] = useState(false);
  const [busyAction, setBusyAction] = useState<'uplift' | 'apply' | null>(null);
  const [feedback, setFeedback] = useState<{ severity: 'success' | 'error' | 'info'; message: string } | null>(null);

  const loadProposals = useCallback(async () => {
    setLoadingProposals(true);
    try {
      const response = await ApiService.getScope3ReclassificationProposals({ period, minConfidence: 0.8 });
      const data = (response as { data?: { unclassifiedPreview?: { proposals?: Scope3Proposal[] }; proposals?: Scope3Proposal[] } })?.data;
      const unclassified = data?.unclassifiedPreview?.proposals || [];
      const all = unclassified.length > 0
        ? unclassified
        : (data?.proposals || []).filter((row) => row.field === 'ghgScope3Category');
      setProposals(all.slice(0, 12));
    } catch (error) {
      setFeedback({
        severity: 'error',
        message: error instanceof Error ? error.message : 'Failed to load Scope 3 proposals',
      });
    } finally {
      setLoadingProposals(false);
    }
  }, [period]);

  useEffect(() => {
    void loadProposals();
  }, [loadProposals]);

  const runActivityUplift = async () => {
    setBusyAction('uplift');
    setFeedback(null);
    try {
      const response = await ApiService.orchestrateActivityDataUplift({ period, applyScope3Changes: false });
      const data = (response as { data?: { metrics?: { scope3ProposalsCount?: number }; scope3Allocation?: { proposalCount?: number } } })?.data;
      const count = data?.scope3Allocation?.proposalCount ?? data?.metrics?.scope3ProposalsCount ?? 0;
      setFeedback({
        severity: 'info',
        message: `Activity uplift finished. ${count} Scope 3 category suggestion(s) ready to confirm.`,
      });
      await loadProposals();
      onResolved?.();
    } catch (error) {
      setFeedback({
        severity: 'error',
        message: error instanceof Error ? error.message : 'Activity data uplift failed',
      });
    } finally {
      setBusyAction(null);
    }
  };

  const confirmApplyProposals = async () => {
    setBusyAction('apply');
    setFeedback(null);
    try {
      const response = await ApiService.applyScope3Reclassifications({
        period,
        confirm: true,
        applyAllUnclassified: true,
        minConfidence: 0.8,
      });
      const data = (response as { data?: { updatedCount?: number; allocatedCount?: number } })?.data;
      const count = data?.updatedCount ?? data?.allocatedCount ?? 0;
      setFeedback({
        severity: 'success',
        message: `Confirmed ${count} Scope 3 category assignment(s). Residual totals were not used.`,
      });
      await loadProposals();
      onResolved?.();
    } catch (error) {
      setFeedback({
        severity: 'error',
        message: error instanceof Error ? error.message : 'Failed to apply Scope 3 reclassifications',
      });
    } finally {
      setBusyAction(null);
    }
  };

  const hideRemediation = !warnings.length && !actions.length && !proposals.length && scope3Quality?.assuranceGradeReady;

  return (
    <Stack spacing={2} sx={{ mb: 2 }}>
      {!hideRemediation ? (
    <Alert severity={scope3Quality?.assuranceGradeReady ? 'success' : 'warning'}>
      <Stack spacing={1.5}>
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
          <Typography variant="subtitle2" fontWeight={700}>
            Scope 3 data quality
          </Typography>
          <Chip
            size="small"
            label={scope3Quality?.assuranceGradeReady ? 'Assurance-grade ready' : 'Needs improvement'}
            color={scope3Quality?.assuranceGradeReady ? 'success' : 'warning'}
          />
          {scope3Quality?.categoryCoverageCount != null ? (
            <Chip
              size="small"
              variant="outlined"
              label={`${scope3Quality.categoryCoverageCount} categories with activity data`}
            />
          ) : null}
          {!scope3Quality?.assuranceGradeReady ? (
            <Chip size="small" variant="outlined" color="success" label="~+10% BRSR readiness" />
          ) : null}
        </Stack>

        {feedback ? (
          <Alert severity={feedback.severity} onClose={() => setFeedback(null)}>
            {feedback.message}
          </Alert>
        ) : null}

        {warnings.map((warning) => (
          <Typography key={warning} variant="body2">
            • {warning}
          </Typography>
        ))}

        {actions.slice(0, 5).map((item, index) => (
          <Box
            key={`${item.category || 'action'}-${index}`}
            sx={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 1,
              p: 1,
              borderRadius: 1,
              bgcolor: 'action.hover',
            }}
          >
            <Box sx={{ flex: 1, minWidth: 200 }}>
              <Typography variant="body2" fontWeight={600}>
                {item.action}
              </Typography>
              {item.category ? (
                <Typography variant="caption" color="text.secondary">
                  Category: {item.category.replace(/_/g, ' ')}
                </Typography>
              ) : null}
            </Box>
            <Button
              size="small"
              component={RouterLink}
              to={item.path || categoryHubLink(item.category)}
              endIcon={<ArrowForwardIcon />}
            >
              {item.category === 'scope3_measurement' ? 'Mark measured' : 'Add data'}
            </Button>
          </Box>
        ))}

        <Box sx={{ p: 1.25, borderRadius: 1, border: '1px solid', borderColor: 'divider' }}>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }} flexWrap="wrap" useFlexGap>
            <Typography variant="body2" fontWeight={700}>
              Suggested Scope 3 category assignments
            </Typography>
            {loadingProposals ? <CircularProgress size={14} /> : (
              <Chip size="small" label={`${proposals.length} ready to confirm`} />
            )}
          </Stack>
          {proposals.length === 0 && !loadingProposals ? (
            <Typography variant="caption" color="text.secondary">
              No high-confidence unclassified reclassifications pending. Run activity uplift to refresh suggestions.
            </Typography>
          ) : (
            proposals.slice(0, 5).map((proposal) => (
              <Typography key={`${proposal.transactionId}-${proposal.to}`} variant="body2" sx={{ mb: 0.5 }}>
                • {proposal.from || 'unclassified'} → {proposal.to.replace(/_/g, ' ')}
                {proposal.confidence != null ? ` (${Math.round(proposal.confidence * 100)}%)` : ''}
              </Typography>
            ))
          )}
        </Box>

        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Button
            size="small"
            variant="contained"
            disabled={busyAction != null || proposals.length === 0}
            onClick={() => void confirmApplyProposals()}
            startIcon={busyAction === 'apply' ? <CircularProgress size={14} color="inherit" /> : undefined}
          >
            Confirm suggested categories
          </Button>
          <Button
            size="small"
            variant="outlined"
            disabled={busyAction != null}
            onClick={() => void runActivityUplift()}
            startIcon={busyAction === 'uplift' ? <CircularProgress size={14} /> : undefined}
          >
            Run activity data uplift
          </Button>
          <Button
            size="small"
            variant="outlined"
            component={RouterLink}
            to={DOCUMENT_UPLOAD_PATH}
          >
            Upload metered bills
          </Button>
          <Button
            size="small"
            variant="outlined"
            component={RouterLink}
            to="/compliance/india?section=brsr-core"
          >
            Open BRSR Core
          </Button>
          <ApplicationWarningResolver
            compact
            period={period}
            warnings={[
              ...(warnings.length ? warnings : actions.map((a) => a.action || ''))
                .filter(Boolean)
                .slice(0, 3)
                .map((message) => ({
                  type: 'readiness_blocked',
                  message: String(message),
                })),
            ]}
            onResolved={onResolved}
          />
        </Stack>
      </Stack>
    </Alert>
      ) : null}
      <Paper variant="outlined" sx={{ p: 2 }}>
        <Scope3Cat5WastePanel />
      </Paper>
    </Stack>
  );
};

export default Scope3RemediationPanel;
